#!/usr/bin/env python3
"""Re-embed assets/sera_source.json into the Godot script for APK export.
Run with: python3 tools/rebuild_model_data.py
"""
import base64
import pathlib
import textwrap

root = pathlib.Path(__file__).resolve().parents[1]
canonical = root / "models" / "core" / "Standard.bbmodel"
source = root / "assets" / "sera_source.json"
target = root / "assets" / "sera_data.gd"
# Keep this Android-compatible JSON alias strictly derived from the single
# editable Blockbench source; never edit either generated file independently.
source.write_bytes(canonical.read_bytes())
encoded = base64.b64encode(source.read_bytes()).decode("ascii")
parts = textwrap.wrap(encoded, 120)
with target.open("w", encoding="utf-8") as file:
    file.write("extends RefCounted\n")
    file.write("## Generated by tools/rebuild_model_data.py\n")
    file.write("const PARTS = [\n")
    for p in parts:
        file.write('    "' + p + '",\n')
    file.write("]\n\n")
    file.write("static func get_json() -> String:\n")
    file.write('    return Marshalls.base64_to_raw("".join(PackedStringArray(PARTS))).get_string_from_utf8()\n')
print(f"Embedded {source.stat().st_size} bytes into {target}")
